<?php require __DIR__.'/../config/functions.php'; require_admin(); $db=get_db(); if($_SERVER['REQUEST_METHOD']==='POST'){ $db->prepare('INSERT INTO admins(username,password,role,status,created_at) VALUES(?,?,?,?,NOW())')->execute(array($_POST['username'],password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role'],1)); } $list=$db->query('SELECT id,username,role,status,created_at FROM admins ORDER BY id DESC')->fetchAll(); page_header('管理员账号'); ?><form class="card" method="post"><h2>新增管理员</h2><input name="username"><input name="password" type="password"><select name="role"><option>operator</option><option>super</option></select><button>创建</button></form><table><?php foreach($list as $r) echo '<tr><td>'.$r['id'].'</td><td>'.esc($r['username']).'</td><td>'.esc($r['role']).'</td><td>'.$r['status'].'</td><td>'.esc($r['created_at']).'</td></tr>'; ?></table><?php page_footer(); ?>
